161	/** Pick the least-committed enabled node (RAM headroom). Falls back to primary. */
162	async function scheduleNode(planRamMB: number) {
163	  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
164	  if (nodes.length === 0) return null;
165	  const loads = await Promise.all(
166	    nodes.map(async (n) => {
167	      const agg = await db.server.findMany({
168	        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
169	        select: { plan: { select: { ramMB: true } } },
170	      });
171	      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
172	      return { node: n, free: n.capacityRamMB - used };
173	    }),
174	  );
175	  loads.sort((a, b) => b.free - a.free);
176	  return loads[0].node;
177	}
