179	/** Validate + price an order without placing it. Throws OrderError on any problem. */
180	export async function orderQuote(intent: OrderIntent) {
181	  const parsed = orderSchema.safeParse(intent);
182	  if (!parsed.success) throw new OrderError(parsed.error.issues[0]?.message ?? "Invalid input.");
183	  const plan = await db.plan.findUnique({ where: { id: intent.planId } });
184	  const os = await db.osTemplate.findUnique({ where: { id: intent.osTemplateId } });
185	  if (!plan?.active || !os?.active) throw new OrderError("Plan or OS not available.");
186	  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
187	    throw new OrderError(
188	      `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
189	    );
190	  }
191	  const term = vpsTerm(Number(intent.termMonths ?? 1));
192	  const ipCents = intent.dedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0;
193	
194	  // Extra root disk, priced per GB/month and multiplied over the term exactly
195	  // like the dedicated-IP add-on (and, like it, NOT discounted by the term or the
196	  // promo — the customer pays the same $/GB whichever term they pick, and renews
197	  // at the same rate). Growth is one-way: this is permanent for the server.
198	  const extraDiskGB = normalizeExtraDiskGB(intent.extraDiskGB);
199	  const extraDiskPerGb = extraDiskGB > 0 ? await extraDiskPerGbCents() : 0;
200	  const extraDiskMonthlyCents = extraDiskCentsAt(extraDiskGB, extraDiskPerGb);
201	  const extraDiskCents = extraDiskMonthlyCents * term.months;
202	  if (effectiveDiskGB(plan.diskGB, extraDiskGB) > EXTRA_DISK_MAX_TOTAL_GB) {
203	    throw new OrderError(`A server's disk tops out at ${EXTRA_DISK_MAX_TOTAL_GB} GB.`);
204	  }
205	
206	  // Seasonal promo = HONEST intro discount on the plan's FIRST-term charge only.
207	  // The regular term price (vpsTermPriceCents) is what renewals bill unchanged in
208	  // worker/billing.ts — so the strikethrough shown on the marketing pages is the
209	  // real renewal price and this discounted value is the real first-term price.
210	  // Marketing displays promoPriceCents(regular) too, so displayed === charged.
211	  // (Dedicated IP is billed at full price; the promo only touches the plan.)
212	  const regularPlanCents = vpsTermPriceCents(plan.priceCents, term.months);
213	  const promo = currentPromo(new Date());
214	  // First-month-free must credit exactly ONE MONTH — not zero a multi-month term.
215	  // A naive promoPriceCents(termTotal) at 100% off would give a 36-month term 3
216	  // YEARS free. So we subtract one month of the plan's rate from the term total.
217	  // For a 1-month term this lands at $0 (genuinely first month free); for a 12/24/
218	  // 36-month term the customer pays the term minus one month. Renewals bill the
219	  // full vpsTermPriceCents unchanged (worker/billing.ts) — displayed === charged.
220	  const planFirstTermCents = promo.firstMonthFree
221	    ? Math.max(0, regularPlanCents - plan.priceCents)
222	    : promoPriceCents(regularPlanCents, promo);
223	
224	  // Optional checkout coupon: a service-locked, term-capped discount on the PLAN
225	  // portion only (not the dedicated-IP or extra-disk add-ons). Never throws for a
226	  // bad code — an invalid coupon leaves the price at full and surfaces `couponError`
227	  // so the deploy preview can show it; the redemption itself (count + per-user +
228	  // per-IP guards) is claimed atomically in placeOrder.
229	  let couponId: string | null = null;
230	  let couponDiscountCents = 0;
231	  let couponLabel = "";
232	  let couponError = "";
233	  let couponMaxRedemptions: number | null = null;
234	  let couponFirstTimeOnly = false;
235	  const code = (intent.couponCode ?? "").trim().toUpperCase();
236	  if (code) {
237	    if (!(await getSettingBool("coupons_enabled", true))) {
238	      couponError = "Promo codes are currently disabled.";
239	    } else {
240	      const coupon = await db.coupon.findUnique({ where: { code } });
241	      if (!coupon) {
242	        couponError = "That code isn’t valid.";
243	      } else {
244	        const verdict = couponOrderDiscountCents(
245	          {
246	            kind: coupon.kind,
247	            value: coupon.value,
248	            serviceKind: coupon.serviceKind,
249	            planSlug: coupon.planSlug,
250	            maxTermMonths: coupon.maxTermMonths,
251	            active: coupon.active,
252	            expiresAt: coupon.expiresAt,
253	            maxRedemptions: coupon.maxRedemptions,
254	            timesRedeemed: coupon.timesRedeemed,
255	            minAmountCents: coupon.minAmountCents,
256	          },
257	          {
258	            serviceKind: "VPS",
259	            planSlug: plan.slug,
260	            planMonthlyCents: plan.priceCents,
261	            termMonths: term.months,
262	            planChargeCents: planFirstTermCents,
263	          },
264	          new Date(),
265	        );
266	        if (verdict.ok) {
267	          couponId = coupon.id;
268	          couponDiscountCents = verdict.discountCents;
269	          couponLabel = verdict.label;
270	          couponMaxRedemptions = coupon.maxRedemptions;
271	          couponFirstTimeOnly = coupon.firstTimeOnly;
272	        } else {
273	          couponError = verdict.error;
274	        }
275	      }
276	    }
277	  }
278	
279	  const chargeCents = planFirstTermCents - couponDiscountCents + ipCents + extraDiskCents;
280	  return {
281	    plan,
282	    os,
283	    term,
284	    chargeCents,
285	    promo,
286	    regularPlanCents,
287	    extraDiskGB,
288	    extraDiskMonthlyCents,
289	    extraDiskCents,
290	    couponId,
291	    couponDiscountCents,
292	    couponLabel,
293	    couponError,
294	    couponMaxRedemptions,
295	    couponFirstTimeOnly,
296	  };
297	}
