300	 * Place an order: validate, charge the wallet (unless a free admin grant),
301	 * create the Server + PROVISION job. Returns the new server id. Does NOT
302	 * redirect. Callers must ensure funds exist (or pass free) — this still
303	 * enforces balance and throws OrderError("Insufficient balance.") otherwise.
304	 *
305	 * `sold` overrides the recomputed price with the one the order was actually SOLD
306	 * at — the card-paid path passes the figure stamped on the Checkout session
307	 * BEFORE the card was charged, so the confirm redirect settles the price the
308	 * customer consented to instead of re-pricing against whatever promo is running
309	 * when they get back (mirrors `chargeCents` in lib/resize.ts applyResize and
310	 * lib/disk-expand.ts applyDiskExpand). The wallet path omits it and pays the
311	 * quote, which it computed moments ago in the same request. See OrderPrice.
312	 */
313	/**
314	 * Claim a checkout coupon in ITS OWN atomic transaction, throwing OrderError on
315	 * any failure so nothing partial survives. Kept separate from the order tx so a
316	 * wallet order can surface the failure before any money moves, and a card order
317	 * (already paid) can swallow it without stranding the paid provision.
318	 *
319	 * Guards, all enforced here: first-time-only (no prior paid server), the
320	 * redemption cap (atomic conditional increment), one-per-account and one-per-IP
321	 * (the two @@unique constraints on CouponRedemption).
322	 */
323	async function claimOrderCoupon(opts: {
324	  couponId: string;
325	  maxRedemptions: number | null;
326	  firstTimeOnly: boolean;
327	  userId: string;
328	  ipHash: string | null;
329	  amountCents: number;
330	}): Promise<void> {
331	  await db.$transaction(async (tx) => {
332	    if (opts.firstTimeOnly) {
333	      const prior = await tx.server.count({ where: { userId: opts.userId, isFree: false } });
334	      if (prior > 0) throw new OrderError("This code is for first-time customers only.");
335	    }
336	    // Atomic conditional increment — the only thing between the last free slot and
337	    // an over-redemption when two orders race for it.
338	    const claim = await tx.coupon.updateMany({
339	      where:
340	        opts.maxRedemptions === null
341	          ? { id: opts.couponId, active: true }
342	          : { id: opts.couponId, active: true, timesRedeemed: { lt: opts.maxRedemptions } },
343	      data: { timesRedeemed: { increment: 1 } },
344	    });
345	    if (claim.count !== 1) throw new OrderError("That code has just been fully claimed.");
346	    try {
347	      await tx.couponRedemption.create({
348	        data: { couponId: opts.couponId, userId: opts.userId, ipHash: opts.ipHash, amountCents: opts.amountCents, context: "order" },
349	      });
350	    } catch {
351	      // Unique violation on (coupon,user) or (coupon,ipHash): already claimed by
352	      // this person. Throwing rolls back the increment above with it.
353	      throw new OrderError("You’ve already used this code.");
354	    }
355	  });
356	}
