11	/**
12	 * Internal-only guard for `maybeRewardReferral` below.
13	 *
14	 * It is exported from this "use server" module, so Next.js registers it as a
15	 * callable action endpoint that would otherwise let anyone POST a raw `userId`
16	 * and mint referral credit for an account they do not own. Its legitimate
17	 * callers are internal: the topUp server action, the
18	 * order-placement flow (lib/order.ts) and the Stripe webhook (lib/stripe.ts).
19	 *
20	 * Three deny rules, in order, each closing a different way in:
21	 *
22	 * 1. SESSION PRESENT ⇒ it must be the account being credited. This is the rule
23	 *    that used to be reached only when a `next-action` header was present.
24	 *
25	 * 2. NO SESSION, BUT DISPATCHED AS AN ACTION ⇒ refuse. An anonymous POST to the
26	 *    action endpoint has no business naming someone else's `userId`.
27	 *
28	 * 3. NON-STRING `userId` ⇒ refuse. Next.js ALSO dispatches actions from a plain
29	 *    no-JavaScript form POST, where the action id travels in the body as
30	 *    `$ACTION_ID_…` and NO `next-action` header is sent at all (see
31	 *    `areAllActionIdsValid` in next/dist/server/app-render/action-handler.js).
32	 *    Rule 2 cannot see that path. React hands such an invocation the FormData as
33	 *    its first argument, so the type check is what actually stops it — an
34	 *    explicit refusal rather than relying on Prisma to choke on the wrong shape.
35	 *
36	 * The old guard's ONLY test was "is the `next-action` header present?", and it
37	 * treated a missing header as proof of a trusted server-to-server call. Rules 1
38	 * and 3 hold whether or not that header exists.
39	 *
40	 * What still gets through, correctly: the Stripe webhook and the checkout
41	 * confirm route (lib/stripe.ts, lib/order.ts). A webhook carries no session
42	 * cookie and is not an action dispatch, and it passes a real string id.
43	 *
44	 * `grantSignupCredit` is NOT here any more. It had exactly one caller — the
45	 * `register` action — and being an export made it a public endpoint whose only
46	 * protection was this guard. It now lives as a private helper inside
47	 * lib/actions.ts, so there is no endpoint to defend.
48	 */
49	async function assertInternalGrowthCaller(userId: string): Promise<void> {
50	  if (typeof userId !== "string" || !userId) throw new Error("FORBIDDEN");
51	  const real = await realUser();
52	  if (real) {
53	    if (real.id !== userId) throw new Error("FORBIDDEN");
54	    return;
55	  }
56	  const h = await headers();
57	  if (h.has("next-action")) throw new Error("FORBIDDEN");
58	}
