68	/**
69	 * Compute the extra wallet credit a coupon grants for a top-up of `baseCents`.
70	 * PERCENT -> baseCents * value%; CREDIT_CENTS -> flat `value` cents.
71	 *
72	 * FIXED_CENTS returns 0 and is refused before it ever reaches here — see the
73	 * guard in `applyCouponToTopup`. It used to return `coupon.value` as a *bonus*,
74	 * which turned a coupon the admin UI advertises as "$5.00 off" into $5.00 of free
75	 * balance. Kept at 0 so that if the guard is ever removed the failure mode is "no
76	 * bonus", not "mints money".
77	 */
78	function couponBonusForTopup(coupon: Coupon, baseCents: number): number {
79	  switch (coupon.kind) {
80	    case "PERCENT":
81	      return Math.round((baseCents * coupon.value) / 100);
82	    case "CREDIT_CENTS":
83	      return coupon.value;
84	    default:
85	      return 0;
86	  }
87	}
