397	export async function placeOrder(
398	  user: User,
399	  intent: OrderIntent,
400	  sold?: OrderPrice | null,
401	  opts?: { ipHash?: string | null },
402	): Promise<string> {
403	  const quote = await orderQuote(intent);
404	  const { plan, os, term, promo, extraDiskGB, extraDiskMonthlyCents, extraDiskCents } = quote;
405	  // Everything below bills off THESE three, never off `quote.chargeCents` /
406	  // `promo` directly: when a sold price is present it is the whole truth about
407	  // what this order costs and what rate it was sold at.
408	  const chargeCents = sold?.chargeCents ?? quote.chargeCents;
409	  const promoPercent = sold?.promoPercent ?? promo.discountPercent;
410	  const promoName = sold?.promoName || promo.name;
411	  // Note the intro discount on the billing document (first term only; renews full).
412	  const promoNote = promoPercent > 0 ? ` · ${promoName} ${promoPercent}% off first term` : "";
413	
414	  const cap = await capacityCheck(plan.id);
415	  if (!cap.ok) throw new OrderError(cap.reason);
416	
417	  let nodeId: string | null = null;
418	  if (intent.nodeId) {
419	    const n = await db.node.findFirst({ where: { id: intent.nodeId, enabled: true } });
420	    if (!n) throw new OrderError("Selected location is not available.");
421	    nodeId = n.id;
422	  } else {
423	    const n = await scheduleNode(plan.ramMB);
424	    nodeId = n?.id ?? null;
425	  }
426	
427	  // Reserve the EFFECTIVE size (plan + upsold extra) — the VM really is that big.
428	  const diskCap = await diskCapacityCheck(nodeId, effectiveDiskGB(plan.diskGB, extraDiskGB));
429	  if (!diskCap.ok) throw new OrderError(diskCap.reason);
430	
431	  const addons = {
432	    malwareScanner: !!intent.addonMalware,
433	    dailyBackup: !!intent.addonBackup,
434	    docker: !!intent.addonDocker,
435	  };
436	  const isAdmin = user.role === "ADMIN";
437	  const freeRequested = !!intent.free && isAdmin;
438	  if (!freeRequested && user.balanceCents < chargeCents) throw new OrderError("Insufficient balance.");
439	
440	  // Claim the coupon BEFORE the order tx, so a wallet order fails cleanly (no
441	  // money moved) if the last slot just went. A free admin grant never consumes a
442	  // customer coupon. On the card-settle path the payment already cleared, so a
443	  // late claim failure must not strand the paid provision — log and continue.
444	  if (!freeRequested && quote.couponId && quote.couponDiscountCents > 0) {
445	    try {
446	      await claimOrderCoupon({
447	        couponId: quote.couponId,
448	        maxRedemptions: quote.couponMaxRedemptions,
449	        firstTimeOnly: quote.couponFirstTimeOnly,
450	        userId: user.id,
451	        ipHash: opts?.ipHash ?? null,
452	        amountCents: quote.couponDiscountCents,
453	      });
454	    } catch (e) {
455	      if (!sold) throw e; // wallet path: nothing charged yet — surface it
456	      console.error(`[order] coupon claim failed on a paid order for ${user.id}`, e);
457	    }
458	  }
459	
460	  const newKey = (intent.sshPublicKey ?? "").trim();
461	  const keyName = (intent.sshKeyName ?? "deploy-key").slice(0, 60);
462	
463	  let server;
464	  try {
465	    server = await db.$transaction(async (tx) => {
