475	/**
476	 * Enforcement for an unpaid volume past grace: detach only, never destroy.
477	 * An ATTACHED volume is flipped to DETACHED and a VOLUME_DETACH job is queued
478	 * (both in one transaction, so we never mark it detached without doing it).
479	 * The underlying disk — and every byte on it — is left intact.
480	 */
481	async function detachUnpaidVolume(
482	  volume: {
483	    id: string;
484	    userId: string;
485	    name: string;
486	    serverId: string | null;
487	    status: string;
488	    expiresAt: Date | null;
489	  },
490	  priceCents: number,
491	  now: Date
492	) {
493	  if (volume.status !== "ATTACHED") {
494	    // Nothing to detach (PENDING / already DETACHED) — just keep nagging.
495	    await notifyOnce(
496	      now,
497	      volume.userId,
498	      volume.name,
499	      "volume unpaid",
500	      `Volume "${volume.name}" is unpaid`,
501	      `This volume is overdue by ${money(priceCents)}/mo. Your data is retained, but the volume may be removed if it stays unpaid past ${ymd(reclaimAt(volume.expiresAt!))}. Top up to keep it.`,
502	      VOLUME_HREF
503	    );
504	    return;
505	  }
506	
507	  // Respect the one-in-flight-job guard so we don't collide with a user or
508	  // worker operation already running on that server; retry on the next sweep.
509	  if (volume.serverId) {
510	    const busy = await db.job.count({
511	      where: { serverId: volume.serverId, status: { in: ["QUEUED", "RUNNING"] } },
512	    });
513	    if (busy > 0) return;
514	  }
515	
516	  try {
517	    await db.$transaction(async (tx) => {
518	      const flipped = await tx.volume.updateMany({
519	        where: { id: volume.id, status: "ATTACHED" },
520	        data: { status: "DETACHED" },
521	      });
522	      if (flipped.count === 0) throw new AlreadyHandledError(`volume ${volume.id}`);
523	      await tx.job.create({
524	        data: { type: "VOLUME_DETACH", serverId: volume.serverId, payload: { volumeId: volume.id } },
525	      });
526	      await tx.auditLog.create({
527	        data: {
528	          userId: volume.userId,
529	          action: "billing.volume_detached_unpaid",
530	          detail: `volume ${volume.id} ${volume.name}`,
531	        },
532	      });
533	    });
534	  } catch (e) {
535	    if (e instanceof AlreadyHandledError) return;
536	    throw e;
537	  }
538	
539	  await notify(
540	    volume.userId,
541	    `Volume "${volume.name}" detached — payment overdue`,
542	    `We couldn't collect ${money(priceCents)} for this volume, so it was detached from your server. Nothing was deleted: all data on the volume is retained and re-attaches exactly as it was once you top up and renew. If it stays unpaid past ${ymd(reclaimAt(volume.expiresAt!))} the volume may be removed.`,
543	    VOLUME_HREF
544	  );
545	  console.log(`${LOG} detached unpaid volume ${volume.id} (${volume.name})`);
546	}
