602	/**
603	 * Renewal sweep for the add-on products. Safe to call as often as you like:
604	 * each phase only acts on rows whose `expiresAt` is genuinely in the past, and
605	 * every charge advances `expiresAt` in the same transaction, so repeated runs
606	 * are no-ops rather than repeat charges.
607	 *
608	 * Wire into the worker loop next to `billingSweep()` (see worker/index.ts).
609	 */
610	export async function productRenewalSweep(): Promise<void> {
611	  const now = new Date();
612	  await phase("email upcoming warnings", () => emailUpcomingWarnings(now));
613	  await phase("email renewals", () => emailDueSweep(now));
614	  await phase("volume upcoming warnings", () => volumeUpcomingWarnings(now));
615	  await phase("volume renewals", () => volumeDueSweep(now));
616	  await phase("hosting renewals", () => hostingDueSweep(now));
617	}
