537	              ? [
538	                  {
539	                    description: `${extraDiskLabel(server.extraDiskGB)} — ${server.hostname} (permanent, $${(extraDiskMonthlyCents / 100).toFixed(2)}/mo)`,
540	                    qty: 1,
541	                    unitCents: extraDiskCents,
542	                    amountCents: extraDiskCents,
543	                  },
544	                ]
545	              : []),
546	          ],
547	        }),
