/**
 * Managed first-month-free promotion — the atomic redemption core.
 *
 * This mirrors lib/order.ts `claimOrderCoupon`: a conditional INSERT guarded by
 * two @@unique constraints (PromoRedemption `@@unique([promoId,userId])` and
 * `@@unique([promoId,ipHash])`) that runs INSIDE the order's charge transaction.
 * If the insert violates either constraint (this account OR this IP already
 * redeemed) it returns `{ claimed: false }` — it never throws for that case — so
 * the caller can charge the FULL price and still complete the order.
 *
 * THE MONEY RULE (owner will review this file personally):
 *   - The free-month credit is applied to an order ONLY when `claimed === true`.
 *   - If the claim is lost (already redeemed by account/IP) OR the promo is
 *     switched off via the `first_month_free_enabled` setting, the customer is
 *     charged the FULL price. The order still succeeds — it just isn't free.
 *   - The caps are FIXED at 1/account + 1/IP and are enforced ONLY by the two
 *     unique constraints. There is no configurable cap to drift out of sync.
 *
 * WHY A TYPED VIEW instead of `db.promoRedemption` directly: the Prisma client in
 * this tree is symlinked from prod and is only regenerated at deploy time, so its
 * types do not yet know about the new PromoRedemption model. Rather than sprinkle
 * `as any` across four money-critical order flows, every raw-delegate access is
 * contained HERE behind `promoDelegate(...)`, and the rest of the codebase calls
 * the strongly-typed helpers below. When the client is regenerated the runtime is
 * identical; only these casts become redundant.
 */

import { Prisma } from "@prisma/client";
import { db } from "./db";

/** The single managed promo id. */
export const FIRST_MONTH_FREE_PROMO_ID = "first-month-free";

/** Products the promo can be granted on (matches PromoRedemption.serviceType). */
export type PromoServiceType = "VPS" | "HOSTING" | "EMAIL" | "GAME";

/** A minimal, honestly-typed shape of the row we read back. */
export type PromoRedemptionRow = {
  id: string;
  promoId: string;
  userId: string;
  ipHash: string | null;
  serviceType: string;
  campaign: string;
  orderRef: string | null;
  renewed: boolean;
  renewedAt: Date | null;
  chargedCents: number;
  createdAt: Date;
};

/**
 * The subset of the PromoRedemption Prisma delegate this module uses, typed by
 * hand so the call sites stay type-checked even before the client is regenerated.
 */
type PromoDelegate = {
  create(args: {
    data: {
      promoId?: string;
      userId: string;
      ipHash: string | null;
      serviceType: string;
      campaign: string;
      orderRef?: string | null;
      chargedCents: number;
    };
    select?: { id: true };
  }): Promise<{ id: string }>;
  findUnique(args: {
    where: { promoId_userId: { promoId: string; userId: string } };
    select?: { id: true };
  }): Promise<{ id: string } | null>;
  findFirst(args: {
    where: { promoId: string; ipHash: string };
    select?: { id: true };
  }): Promise<{ id: string } | null>;
  findMany(args?: {
    where?: { promoId?: string; renewed?: boolean };
    orderBy?: { createdAt: "asc" | "desc" };
  }): Promise<PromoRedemptionRow[]>;
  updateMany(args: {
    where: { promoId: string; orderRef: string; renewed?: boolean };
    data: { renewed: boolean; renewedAt: Date };
  }): Promise<{ count: number }>;
  update(args: {
    where: { id: string };
    data: { orderRef?: string | null; chargedCents?: number };
  }): Promise<{ id: string }>;
  count(args?: { where?: { promoId?: string; renewed?: boolean } }): Promise<number>;
};

/** Anything that carries a `promoRedemption` delegate — the client or a tx client. */
type PromoClient = Prisma.TransactionClient | typeof db;

/** The one place the stale-client cast lives. */
function promoDelegate(client: PromoClient): PromoDelegate {
  return (client as unknown as { promoRedemption: PromoDelegate }).promoRedemption;
}

/** Is the sitewide first-month-free offer switched on? (Owner toggle.) */
export async function firstMonthFreeEnabled(): Promise<boolean> {
  // Imported lazily so this module stays importable from the worker (no request
  // scope) without dragging server-only settings wiring into every consumer.
  const { getSettingBool } = await import("./settings");
  return getSettingBool("first_month_free_enabled", true);
}

/**
 * Read-only pre-check: could THIS user / IP still claim the promo? Mirrors
 * `orderCouponClaimable` — used before the wallet balance gate so a first-time,
 * $0-balance customer can be quoted the free (zero) price and pass the gate,
 * while a repeat account/IP is quoted (and gated against) the full price. It is
 * advisory only; the authoritative decision is the atomic `claimFirstMonthFree`
 * inside the charge tx, which is the sole arbiter of whether money is discounted.
 */
export async function firstMonthFreeEligible(
  userId: string,
  ipHash: string | null,
): Promise<boolean> {
  const d = promoDelegate(db);
  const byUser = await d.findUnique({
    where: { promoId_userId: { promoId: FIRST_MONTH_FREE_PROMO_ID, userId } },
    select: { id: true },
  });
  if (byUser) return false;
  if (ipHash) {
    const byIp = await d.findFirst({
      where: { promoId: FIRST_MONTH_FREE_PROMO_ID, ipHash },
      select: { id: true },
    });
    if (byIp) return false;
  }
  return true;
}

export type ClaimResult = { claimed: true; id: string } | { claimed: false };

/**
 * THE ATOMIC CLAIM. Conditional INSERT of a PromoRedemption inside the caller's
 * charge transaction. Returns `{ claimed: true, id }` on success, or
 * `{ claimed: false }` when the row already exists for this account OR this IP
 * (Prisma P2002 on either unique constraint). Any OTHER database error is
 * rethrown so it rolls the whole charge tx back — a lost claim is expected and
 * cheap; an unexpected failure must not silently grant a free month.
 *
 * `orderRef` is usually still unknown here (the server/account id is generated
 * later in the same tx), so it is filled in afterwards via `setPromoOrderRef`.
 */
export async function claimFirstMonthFree(
  tx: Prisma.TransactionClient,
  opts: {
    userId: string;
    ipHash: string | null;
    serviceType: PromoServiceType;
    campaign: string;
    chargedCents: number;
    orderRef?: string | null;
  },
): Promise<ClaimResult> {
  try {
    const row = await promoDelegate(tx).create({
      data: {
        promoId: FIRST_MONTH_FREE_PROMO_ID,
        userId: opts.userId,
        ipHash: opts.ipHash,
        serviceType: opts.serviceType,
        campaign: opts.campaign,
        orderRef: opts.orderRef ?? null,
        chargedCents: opts.chargedCents,
      },
      select: { id: true },
    });
    return { claimed: true, id: row.id };
  } catch (e) {
    if (e instanceof Prisma.PrismaClientKnownRequestError && e.code === "P2002") {
      // Unique violation on (promo,user) or (promo,ipHash): already redeemed.
      return { claimed: false };
    }
    throw e;
  }
}

/**
 * Backfill the created server/account/subscription id (and the final charged
 * amount) onto a redemption we just claimed, in the same tx. Kept off the claim
 * itself because the resource id is minted after the claim within the tx.
 */
export async function setPromoOrderRef(
  tx: Prisma.TransactionClient,
  redemptionId: string,
  orderRef: string,
  chargedCents: number,
): Promise<void> {
  await promoDelegate(tx).update({
    where: { id: redemptionId },
    data: { orderRef, chargedCents },
  });
}

/**
 * Mark the promo redemption anchored to `orderRef` as RENEWED, the first time
 * that service bills its SECOND term. Idempotent: the `renewed: false` guard
 * means a repeated/racing renewal sweep matches zero rows and does nothing.
 * Called inside the renewal charge tx so it commits with the money.
 */
export async function markPromoRenewed(
  tx: Prisma.TransactionClient,
  orderRef: string,
): Promise<void> {
  await promoDelegate(tx).updateMany({
    where: { promoId: FIRST_MONTH_FREE_PROMO_ID, orderRef, renewed: false },
    data: { renewed: true, renewedAt: new Date() },
  });
}

/** One-month credit for a flat-priced term (used by the game flow). */
export function firstMonthCreditCents(termPriceCents: number, termMonths: number): number {
  if (termMonths <= 1) return termPriceCents; // whole (single-month) term is free
  const oneMonth = Math.round(termPriceCents / termMonths);
  return Math.min(termPriceCents, oneMonth);
}

// ---------------------------------------------------------------------------
// Campaign tag (from the /go/<slug>?c=<campaign> cookie)
// ---------------------------------------------------------------------------

/** The cookie the /go link sets and the order flows read for attribution. */
export const PROMO_CAMPAIGN_COOKIE = "nx_promo_campaign";

/** Keep campaign tags to a safe, bounded alnum-dash slug (≤40). */
export function sanitizeCampaign(raw: string | null | undefined): string {
  return String(raw ?? "")
    .replace(/[^a-zA-Z0-9-]/g, "")
    .slice(0, 40);
}

/**
 * Read + sanitize the campaign tag from an already-resolved cookie jar. Takes the
 * jar (not `cookies()`) so this module never imports `next/headers` — that keeps
 * it importable from the worker, which has no request scope.
 */
export function promoCampaignFromCookie(jar: {
  get(name: string): { value: string } | undefined;
}): string {
  return sanitizeCampaign(jar.get(PROMO_CAMPAIGN_COOKIE)?.value);
}

// ---------------------------------------------------------------------------
// Admin stats
// ---------------------------------------------------------------------------

export type PromoCampaignStat = {
  campaign: string;
  total: number;
  renewed: number;
};

export type PromoStats = {
  total: number;
  renewed: number;
  /** renewed / total, 0..1. */
  conversion: number;
  byCampaign: PromoCampaignStat[];
  /** Approximate recovered revenue (one renewal term at list price), in cents. */
  revenueRecoveredCents: number;
  /** True when revenueRecovered had to fall back to an approximation. */
  revenueApproximate: boolean;
};

/**
 * Aggregate redemption + conversion stats for the admin Promotions page.
 *
 * Revenue recovered is APPROXIMATE: for each renewed redemption we price ONE
 * renewal term at the underlying plan's current list price (VPS/hosting use the
 * plan monthly price; email/game use their stored term price). It is a lower/near
 * estimate — it ignores add-ons and multi-term VPS — hence `revenueApproximate`.
 */
export async function promoStats(): Promise<PromoStats> {
  const rows = await promoDelegate(db).findMany({
    where: { promoId: FIRST_MONTH_FREE_PROMO_ID },
    orderBy: { createdAt: "desc" },
  });

  const total = rows.length;
  const renewedRows = rows.filter((r) => r.renewed);
  const renewed = renewedRows.length;

  const byCampaignMap = new Map<string, PromoCampaignStat>();
  for (const r of rows) {
    const key = r.campaign || "(organic)";
    const stat = byCampaignMap.get(key) ?? { campaign: key, total: 0, renewed: 0 };
    stat.total += 1;
    if (r.renewed) stat.renewed += 1;
    byCampaignMap.set(key, stat);
  }
  const byCampaign = [...byCampaignMap.values()].sort((a, b) => b.total - a.total);

  // Approximate recovered revenue: one renewal term at list price per renewed row.
  let revenueRecoveredCents = 0;
  let revenueApproximate = false;
  const refs = (type: PromoServiceType) =>
    renewedRows.filter((r) => r.serviceType === type && r.orderRef).map((r) => r.orderRef as string);

  const vpsRefs = refs("VPS");
  const gameRefs = refs("GAME");
  const serverRefs = [...vpsRefs, ...gameRefs];
  if (serverRefs.length) {
    const servers = await db.server.findMany({
      where: { id: { in: serverRefs } },
      select: { id: true, plan: { select: { priceCents: true } }, gamePlan: { select: { priceCents: true } } },
    });
    for (const s of servers) {
      revenueRecoveredCents += s.gamePlan?.priceCents ?? s.plan?.priceCents ?? 0;
    }
    revenueApproximate = true;
  }

  const hostRefs = refs("HOSTING");
  if (hostRefs.length) {
    const accounts = await db.hostingAccount.findMany({
      where: { id: { in: hostRefs } },
      select: { plan: { select: { priceCents: true } } },
    });
    for (const a of accounts) revenueRecoveredCents += a.plan?.priceCents ?? 0;
    revenueApproximate = true;
  }

  const emailRefs = refs("EMAIL");
  if (emailRefs.length) {
    const subs = await db.emailSubscription.findMany({
      where: { id: { in: emailRefs } },
      select: { emailPlan: { select: { priceCents: true } } },
    });
    for (const s of subs) revenueRecoveredCents += s.emailPlan?.priceCents ?? 0;
    revenueApproximate = true;
  }

  return {
    total,
    renewed,
    conversion: total > 0 ? renewed / total : 0,
    byCampaign,
    revenueRecoveredCents,
    revenueApproximate,
  };
}

