"use server";

import { revalidatePath } from "next/cache";
import { requireArea } from "@/lib/rbac";
import { setSetting } from "@/lib/settings";

/**
 * Flip the sitewide first-month-free promo on or off. Platform-only (ADMIN).
 * When off, every order flow charges full price and claims no PromoRedemption —
 * the caps (1/account + 1/IP) stay enforced by the DB unique constraints either
 * way, so there is nothing else to configure here.
 */
export async function setFirstMonthFreeEnabled(enabled: boolean): Promise<{ ok: true }> {
  await requireArea("platform");
  await setSetting("first_month_free_enabled", enabled ? "true" : "false");
  revalidatePath("/admin/promotions");
  return { ok: true };
}

"use client";

import { useState, useTransition } from "react";
import { setFirstMonthFreeEnabled } from "@/app/admin/promotions/actions";

/** Owner on/off switch for the first-month-free promo. */
export function PromoToggle({ enabled }: { enabled: boolean }) {
  const [on, setOn] = useState(enabled);
  const [pending, start] = useTransition();

  function toggle() {
    const next = !on;
    setOn(next); // optimistic
    start(async () => {
      try {
        await setFirstMonthFreeEnabled(next);
      } catch {
        setOn(!next); // revert on failure
      }
    });
  }

  return (
    <div className="flex items-center gap-3">
      <button
        type="button"
        role="switch"
        aria-checked={on}
        onClick={toggle}
        disabled={pending}
        className={`relative inline-flex h-6 w-11 items-center rounded-full transition ${
          on ? "bg-emerald-500" : "bg-slate-600"
        } ${pending ? "opacity-60" : ""}`}
      >
        <span
          className={`inline-block h-4 w-4 transform rounded-full bg-white transition ${
            on ? "translate-x-6" : "translate-x-1"
          }`}
        />
      </button>
      <span className={`text-sm font-medium ${on ? "text-emerald-300" : "text-slate-400"}`}>
        {on ? "Enabled" : "Disabled"}
      </span>
    </div>
  );
}

/** Sanitize a campaign tag to the same alnum-dash slug (≤40) the /go route accepts. */
function sanitize(raw: string): string {
  return raw.replace(/[^a-zA-Z0-9-]/g, "").slice(0, 40);
}

/**
 * Ad-link generator: type a campaign name, get the copy-ready /go link. `base` is
 * the public host (e.g. "nxeon.cloud"). The tag flows to the PromoRedemption's
 * `campaign` field, so conversions bucket by campaign on this page.
 */
export function AdLinkGenerator({ base }: { base: string }) {
  const [campaign, setCampaign] = useState("");
  const [copied, setCopied] = useState(false);
  const clean = sanitize(campaign);
  const link = clean
    ? `${base}/go/first-month-free?c=${clean}`
    : `${base}/go/first-month-free?c=<campaign>`;

  async function copy() {
    if (!clean) return;
    try {
      await navigator.clipboard.writeText(link);
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    } catch {
      /* clipboard blocked — the field is selectable as a fallback */
    }
  }

  return (
    <div className="space-y-3">
      <div>
        <label className="label">Campaign name</label>
        <input
          className="input"
          value={campaign}
          onChange={(e) => setCampaign(e.target.value)}
          placeholder="meta-spring-launch"
        />
        {campaign && clean !== campaign && (
          <p className="mt-1 text-xs text-amber-400">
            Trimmed to <span className="font-mono">{clean || "(empty)"}</span> — tags are alnum-dash, ≤40 chars.
          </p>
        )}
      </div>
      <div className="flex items-center gap-2">
        <code className="flex-1 overflow-x-auto whitespace-nowrap rounded-lg border border-slate-700 bg-slate-900/60 px-3 py-2 text-xs text-slate-300">
          {link}
        </code>
        <button
          type="button"
          onClick={copy}
          disabled={!clean}
          className="btn-secondary shrink-0 text-sm disabled:opacity-50"
        >
          {copied ? "Copied" : "Copy"}
        </button>
      </div>
    </div>
  );
}

