import { requireArea } from "@/lib/rbac";
import { getSettingBool } from "@/lib/settings";
import { promoStats } from "@/lib/promo-redemption";
import { PageHeader, StatCard, fmtMoney } from "@/components/ui/primitives";
import { PromoToggle, AdLinkGenerator } from "@/components/admin/PromotionsControls";

export const dynamic = "force-dynamic";

/** Public host for the ad-link generator, from APP_URL (falls back to nxeon.cloud). */
function publicBase(): string {
  const raw = process.env.APP_URL ?? "https://nxeon.cloud";
  return raw.replace(/^https?:\/\//, "").replace(/\/$/, "");
}

export default async function AdminPromotions() {
  await requireArea("platform");
  const [enabled, stats] = await Promise.all([
    getSettingBool("first_month_free_enabled", true),
    promoStats(),
  ]);
  const pct = (n: number) => `${(n * 100).toFixed(n > 0 && n < 0.01 ? 2 : 0)}%`;

  return (
    <div className="space-y-6">
      <PageHeader
        title="Promotions"
        sub="The sitewide first-month-free offer — redemptions, caps, ad links and renewal conversion."
      />

      {/* The promo + its toggle + fixed caps */}
      <div className="card space-y-4">
        <div className="flex flex-wrap items-start justify-between gap-4">
          <div>
            <p className="section-label">First month free</p>
            <p className="mt-1 text-sm text-slate-400">
              New customers get their first term free on VPS, Web Hosting, Business Email and Game
              servers, then renew at the regular price. Applied atomically at checkout.
            </p>
          </div>
          <div className="text-right">
            <p className="section-label mb-2">Status</p>
            <PromoToggle enabled={enabled} />
          </div>
        </div>
        <div className="rounded-lg border border-slate-700 bg-slate-900/40 px-4 py-3 text-sm text-slate-300">
          <span className="font-medium text-slate-200">Caps (fixed):</span> 1 redemption per account
          and 1 per IP address. Enforced by unique database constraints on the redemption — there is
          no per-cap configuration by design.{" "}
          {enabled ? (
            <span className="text-emerald-300">The promo is live.</span>
          ) : (
            <span className="text-amber-400">The promo is off — all orders charge full price.</span>
          )}
        </div>
      </div>

      {/* Renewal stats */}
      <div className="grid grid-cols-2 gap-4 lg:grid-cols-4">
        <StatCard label="Total redemptions" value={String(stats.total)} />
        <StatCard label="Renewed (2nd term)" value={String(stats.renewed)} />
        <StatCard label="Conversion" value={pct(stats.conversion)} />
        <StatCard label="Revenue recovered" value={fmtMoney(stats.revenueRecoveredCents)} />
      </div>
      {stats.revenueApproximate && (
        <p className="-mt-2 text-xs text-slate-500">
          Revenue recovered is approximate: one renewal term per converted redemption, priced at the
          underlying plan&apos;s current list price (ignores add-ons and multi-term VPS).
        </p>
      )}

      {/* Per-campaign breakdown */}
      <div className="card overflow-x-auto p-0">
        <p className="section-label px-4 pt-4">By campaign</p>
        {stats.byCampaign.length === 0 ? (
          <p className="px-4 py-8 text-sm text-slate-400">
            No redemptions yet. Share an ad link below to start attributing conversions.
          </p>
        ) : (
          <table className="table-shell mt-2 min-w-[520px]">
            <thead>
              <tr>
                <th>Campaign</th>
                <th className="text-right">Redemptions</th>
                <th className="text-right">Renewed</th>
                <th className="text-right">Conversion</th>
              </tr>
            </thead>
            <tbody>
              {stats.byCampaign.map((c) => (
                <tr key={c.campaign}>
                  <td className="font-mono text-sm">{c.campaign}</td>
                  <td className="text-right">{c.total}</td>
                  <td className="text-right">{c.renewed}</td>
                  <td className="text-right">{c.total > 0 ? pct(c.renewed / c.total) : "—"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      {/* Ad-link generator */}
      <div className="card space-y-3">
        <div>
          <p className="section-label">Ad link generator</p>
          <p className="mt-1 text-sm text-slate-400">
            Build a campaign-tagged link for an ad or post. The tag rides a cookie into checkout and
            buckets conversions above. It also flows to the Meta/Google pixel for attribution.
          </p>
        </div>
        <AdLinkGenerator base={publicBase()} />
      </div>
    </div>
  );
}

